{
  "title": "Job hunting and language issues in Austria and Slovakia",
  "topics": [
    {
      "id": "job-hunting-abroad",
      "title": "Finding work abroad",
      "claims": [
        {
          "text": "LinkedIn is recommended for job search.",
          "evidence": [18]
        },
        {
          "text": "Around 100 applications yielded only 3 interviews.",
          "evidence": [21]
        },
        {
          "text": "Most vacancies (95%) require local language proficiency.",
          "evidence": [26]
        },
        {
          "text": "Some hires occur despite poor language skills.",
          "evidence": [29]
        },
        {
          "text": "Higher education rarely influences hiring decisions.",
          "evidence": [32]
        },
        {
          "text": "Salary in Europe is generally higher than in Ukraine, but many overlook it.",
          "evidence": [35]
        },
        {
          "text": "Employer often asks for B2 language level, sometimes B1, and rarely demands a certificate.",
          "evidence": [46]
        }
      ]
    },
    {
      "id": "language-barriers",
      "title": "Language requirements and daily life",
      "claims": [
        {
          "text": "German is the primary language spoken in Austria, but English is used in many workplaces.",
          "evidence": [14, 15]
        },
        {
          "text": "The speaker feels insecure using English outside work.",
          "evidence": [55]
        },
        {
          "text": "Learning the local language improves confidence in everyday situations.",
          "evidence": [47]
        }
      ]
    },
    {
      "id": "experience-and-interviews",
      "title": "Experience and interview chances",
      "claims": [
        {
          "text": "Even candidates with 3 years of experience face low conversion rates (100 applications → 3 interviews).",
          "evidence": [21]
        },
        {
          "text": "A friend was invited to a Mid-level interview despite having no commercial experience, likely due to a master's degree.",
          "evidence": [28]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Should the speaker stay in Austria or consider moving elsewhere?",
      "evidence": [58]
    }
  ]
